frames={}
for s in U:
 d=pd.read_csv(os.path.join('../persistent/stock_data',s+'.csv')); d['date']=pd.to_datetime(d['date']); frames[s]=d.sort_values('date').set_index('date')
prices=pd.concat({s:np.log(frames[s]['close']) for s in U},axis=1).sort_index()
vol=pd.concat({s:pd.to_numeric(frames[s]['volume'],errors='coerce') for s in U},axis=1).sort_index()
ret=prices.diff(20); vr=(vol.rolling(20,min_periods=15).mean()/vol.rolling(60,min_periods=40).mean()).clip(.5,2); factor=ret*vr
ics=[]; dates=[]; ns=[]; turnover=[]; prev=None
for dt in factor.index:
 if not (pd.Timestamp('2020-01-02')<=dt<=pd.Timestamp('2026-07-15')): continue
 z=pd.concat([factor.loc[dt],(prices.shift(-10)-prices).loc[dt]],axis=1).dropna()
 if len(z)>=8:
  q=spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic
  if np.isfinite(q): ics.append(q); dates.append(dt); ns.append(len(z))
 sig=factor.loc[dt].rank(pct=True)
 if prev is not None: turnover.append(np.nanmean(np.abs(sig-prev)))
 prev=sig
ics=np.asarray(ics); print('dates',len(ics),'avg_instruments',np.mean(ns),'coverage',np.mean(ns)/15)
print('IC %.8f ICIR %.8f hit %.5f turnover %.8f'%(ics.mean(),ics.mean()/ics.std(ddof=1),np.mean(ics>0),np.mean(turnover)))
for h in [1,5,10,20]:
 aa=[]; ff=prices.shift(-h)-prices
 for dt in factor.index:
  if not (pd.Timestamp('2020-01-02')<=dt<=pd.Timestamp('2026-07-15')): continue
  z=pd.concat([factor.loc[dt],ff.loc[dt]],axis=1).dropna()
  if len(z)>=8: aa.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
 print('decay',h,'%.8f'%np.nanmean(aa))
for yr in range(2020,2027):
 a=[v for d,v in zip(dates,ics) if d.year==yr]
 if a: print('annual',yr,'%.8f'%np.mean(a),len(a))
print('last_date',dates[-1])

